-- 0003_calendar.sql — the US trading calendar, 2026 to 2030.
--
-- Seeded data, not runtime logic (D-15). N-3 ("a run on Thanksgiving completes and records no
-- fills") and the derived trading day (D-11) both need a calendar that tests can rely on and
-- that cannot shift under them between runs. A few hundred rows are cheaper to trust than a
-- holiday rule that is recomputed every night.
--
-- The rows below are generated by scripts/gen-trading-calendar.py, which stays in the
-- repository as the audit trail — 1826 hand-typed rows would be unverifiable. Regenerate with:
--
--   python3 scripts/gen-trading-calendar.py 2026 2030
--
-- CAVEAT WORTH ACTING ON: these dates are computed from NYSE's published *rules*, not copied
-- from the exchange's published calendar. The rules are stable and the generated dates were
-- spot-checked, but the exchange occasionally closes for something no rule predicts — a state
-- funeral, a hurricane. Check the official calendar before the 14-day acceptance run (§11)
-- depends on it, and correct any difference with a new migration rather than by editing this
-- one.

-- Seed-only: 0001's default privileges grant the application SELECT and INSERT on every new
-- table, and this one has no business being inserted into at run time. 0009 revokes that
-- INSERT along with the other explicit grants.
CREATE TABLE trading_calendar (
  cal_date    date    PRIMARY KEY,
  is_session  boolean NOT NULL,
  -- A session that closes at 13:00 instead of 16:00. Recorded because it changes nothing for
  -- daily bars today, and would change everything if intraday data ever arrived.
  early_close boolean NOT NULL DEFAULT false,
  -- The holiday name, 'weekend', or NULL for an ordinary full session.
  note        text,
  CONSTRAINT trading_calendar_early_close_implies_session
    CHECK (NOT early_close OR is_session)
);

-- Asking about a date the seed does not cover must fail loudly.
--
-- Without this, the first day of 2031 would quietly answer "not a session" for every date,
-- the nightly job would skip every night, and nothing would appear to be wrong — the runs
-- would simply stop and the record would stop accruing. That is the worst possible failure
-- for this product, so it raises instead.
CREATE FUNCTION is_trading_day(d date) RETURNS boolean
LANGUAGE plpgsql STABLE AS $$
DECLARE
  session boolean;
BEGIN
  SELECT is_session INTO session FROM trading_calendar WHERE cal_date = d;
  IF NOT FOUND THEN
    RAISE EXCEPTION
      'no trading calendar entry for %: extend the seed past its current range', d;
  END IF;
  RETURN session;
END $$;

-- Generated by scripts/gen-trading-calendar.py. Do not edit by hand.
-- Range 2026-01-01 to 2030-12-31.
